public class Main {
    static void check(int[] nums, int target, int[] want) {
        int[] got = new Solution().twoSum(nums, target);
        if (!java.util.Arrays.equals(got, want)) throw new RuntimeException(java.util.Arrays.toString(got));
    }
    public static void main(String[] args) {
        check(new int[] {2, 7, 11, 15}, 9, new int[] {0, 1});
        check(new int[] {3, 2, 4}, 6, new int[] {1, 2});
        check(new int[] {3, 3}, 6, new int[] {0, 1});
        check(new int[] {-1, -2, -3, -4, -5}, -8, new int[] {2, 4});
        check(new int[] {1, 2}, 7, new int[] {});
    }
}

