#include <unordered_map>
#include <vector>
using namespace std;

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> seen;               // value -> position
        for (int i = 0; i < (int)nums.size(); i++) {
            int need = target - nums[i];            // the partner
            auto it = seen.find(need);              // check first ...
            if (it != seen.end()) {
                return {it->second, i};
            }
            seen[nums[i]] = i;                      // ... then write
        }
        return {};
    }
};

